xpath.script:
(function () {
    function prepareYouTubeFrame(frame) {
        var source = frame.getAttribute('src') || '';
        if (!/youtube(?:-nocookie)?\.com\/embed\//i.test(source) || frame.dataset.facodiReferrerPolicyApplied) {
            return;
        }
        var embedUrl = new URL(source, window.location.href);
        if (!embedUrl.searchParams.has('widget_referrer')) {
            embedUrl.searchParams.set('widget_referrer', window.location.origin);
            frame.setAttribute('src', embedUrl.toString());
        }
        frame.dataset.facodiReferrerPolicyApplied = '1';
        frame.setAttribute('referrerpolicy', 'origin');
    }

    function prepareYouTubeNode(root) {
        if (!root || root.nodeType !== 1) {
            return;
        }
        if (root.matches('iframe')) {
            prepareYouTubeFrame(root);
        }
        root.querySelectorAll('iframe').forEach(prepareYouTubeFrame);
    }

    var appendChild = Node.prototype.appendChild;
    Node.prototype.appendChild = function (node) {
        prepareYouTubeNode(node);
        return appendChild.call(this, node);
    };

    var insertBefore = Node.prototype.insertBefore;
    Node.prototype.insertBefore = function (node, referenceNode) {
        prepareYouTubeNode(node);
        return insertBefore.call(this, node, referenceNode);
    };

    function installJQueryHook() {
        if (!window.jQuery || !window.jQuery.fn || !window.jQuery.fn.appendTo || window.jQuery.fn.facodiYouTubeHook) {
            return;
        }
        var appendTo = window.jQuery.fn.appendTo;
        window.jQuery.fn.appendTo = function (target) {
            this.each(function () {
                prepareYouTubeNode(this);
            });
            return appendTo.apply(this, arguments);
        };
        window.jQuery.fn.facodiYouTubeHook = true;
    }

    document.addEventListener('DOMContentLoaded', installJQueryHook);
    installJQueryHook();

    new MutationObserver(function (mutations) {
        mutations.forEach(function (mutation) {
            mutation.addedNodes.forEach(prepareYouTubeNode);
        });
    }).observe(document.documentElement, {childList: true, subtree: true});
}());
